```javascript
function sanitizeUserInput(input) {
    // Function to escape special HTML characters
    function escapeHtml(unsafe) {
        return unsafe
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }

    // Ensure the input is a string before escaping
    if (typeof input !== 'string') {
        input = String(input);
    }

    return escapeHtml(input);
}
```

